export class Rectangle {
    static list: Rectangle[] = [];
    x: number
    y: number
    width: number;
    height: number;
    r = 5;
    private _isInside: boolean = false
    constructor(x = 0, y = 0, width = 10, height = 10 ) {
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
        Rectangle.list.push(this);
    }
    public mouseDown(x: number, y: number) {
        console.log('down', x, y);
    }
    public mouseUp(x: number, y: number) {
        console.log('up', x, y);

    }
    public mouseDrag(x: number, y: number) {
        console.log('drag', x, y);
        
    }
    public isInside() {

    }
    public render(ctx: CanvasRenderingContext2D) {


        if (this._isInside) {
            ctx.beginPath();
            ctx.arc(this.x, this.y, this.r,0, Math.PI);
            ctx.closePath();



            ctx.stroke()
        }
        

        ctx.lineWidth = 2;
        ctx.strokeStyle = '#999';
        ctx.beginPath();
        ctx.rect(this.x, this.y , this.width, this.height);
        ctx.closePath();
        ctx.stroke()

    }
}